<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once '../config/database.php';$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);if(!$uid){header('Location: ../auth/login.php');exit;}$q=trim($_GET['q']??'');$results=[];if($q!==''){$like='%'.$q.'%';if($role==='patient'){$pages=[['Appointments','Book or review your appointment calendar','appointments.php'],['Dental Chart','Mark your teeth on the 3D model while booking an appointment','appointments.php'],['Dental Records','Review clinic treatment records','dental_records.php'],['Treatment Plans','Review treatment recommendations','treatment_plans.php'],['Notifications','Review clinic updates','notifications.php']];foreach($pages as $p){if(stripos($p[0],$q)!==false||stripos($p[1],$q)!==false)$results[]=['title'=>$p[0],'detail'=>$p[1],'url'=>$p[2]];}}else{$st=$conn->prepare("SELECT id,first_name,last_name,email FROM users WHERE role='patient' AND (first_name LIKE ? OR last_name LIKE ? OR email LIKE ?) ORDER BY last_name,first_name LIMIT 30");$st->bind_param('sss',$like,$like,$like);$st->execute();foreach($st->get_result()->fetch_all(MYSQLI_ASSOC) as $p){$url=$role==='dentist'?'patient_view.php?id='.$p['id']:($role==='assistant'?'patient_view.php?id='.$p['id']:'users.php?q='.urlencode($q));$results[]=['title'=>$p['first_name'].' '.$p['last_name'],'detail'=>$p['email'].' · Patient','url'=>$url];}$st->close();}}
require '../includes/ui.php';ui_header('Search',$role);ui_sidebar($role,'');?><div class="page-head"><div><div class="eyebrow">SEARCH</div><h1>Search SupremeDent</h1><div class="muted">Find patients or jump to a feature from the top search bar.</div></div></div><section class="card"><form class="directory-search" method="get"><input type="search" name="q" value="<?=e($q)?>" placeholder="Search patients or pages" autofocus><button class="btn btn-primary">Search</button></form><?php if($q===''):?><div class="empty">Type something to search.</div><?php elseif(!$results):?><div class="empty">No results found for “<?=e($q)?>”.</div><?php else:?><div class="search-results"><?php foreach($results as $r):?><a class="search-result" href="<?=e($r['url'])?>"><div><strong><?=e($r['title'])?></strong><small><?=e($r['detail'])?></small></div><span>Open</span></a><?php endforeach;?></div><?php endif;?></section><?php ui_footer();?>
